-- Seed the Order Information sections with the copy previously built into the
-- page. Only fills an empty slot, so content the owner has saved is kept.
UPDATE `site_settings` SET `data` = JSON_SET(`data`, '$.orderInfo', CAST('[{"icon": "pickup", "title": "Pickup", "body": "All standard orders are available for local pickup. Exact pickup details are shared after your order is confirmed — they are not published on the website."}, {"icon": "delivery", "title": "Local delivery", "body": "Local delivery is available within our approved Charlotte service area. Delivery arrangements are confirmed when your order is reviewed."}, {"icon": "noShipping", "title": "No shipping", "body": "We do not offer nationwide shipping at this time. TakeASweet is local love only — for now!"}, {"icon": "customOrders", "title": "Custom orders", "body": "Custom dessert requests are welcome for birthdays, showers, and celebrations. A request is not a confirmed order: every request is reviewed first, and large or custom orders may require approval and a deposit. Wedding orders are not accepted."}, {"icon": "payment", "title": "Payment", "body": "Standard menu items are paid for online at checkout when online ordering is open. Custom orders are invoiced after approval."}]' AS JSON)) WHERE `id` = 1 AND JSON_EXTRACT(`data`, '$.orderInfo') IS NULL;
